// DiabloDoom built-in pistol sprite, in Doom patch format.
// See d_pistol_sprite.c (generated by assets/make_pistol_sprite.py).

#ifndef __D_PISTOL_SPRITE__
#define __D_PISTOL_SPRITE__

#include "doomtype.h"
#include "v_patch.h"
#include "d_diablo.h"

// The embedded pistol patch (48x18, real patch transparency), for
// the draw sites that prefer a WAD pickup sprite: the pistol has
// none in any IWAD, so they use this one instead of the opaque
// compiled icon.
patch_t *D_PistolSprite(void);

// Built-in patch standing in for a WAD pickup sprite, for a gun the
// loaded IWAD cannot supply (today: the pistol).  NULL otherwise.
// Implemented in d_diablo.c next to D_ItemWadSpriteName.
patch_t *D_ItemBuiltinPatch(const diablo_itemdef_t *def);

#endif
